import {
  SwitchRoot,
  SwitchControl,
  SwitchThumb,
  SwitchLabel,
  SwitchHiddenInput,
} from '@uifn/components-react/switch'
import '@uifn/components/styles.css'

export function Example() {
  return (
    <SwitchRoot defaultChecked name="darkMode">
      <SwitchControl type="button">
        <SwitchThumb />
      </SwitchControl>
      <SwitchLabel>Automatic updates</SwitchLabel>
      <SwitchHiddenInput />
    </SwitchRoot>
  )
}

